50|     const regions = new Map<string, RegionReport>();
51|     const regionOf = (name: string): RegionReport => {
52|       let r = regions.get(name);
53|       if (!r) {
54|         r = {
55|           region: name,
56|           hives: 0,
57|           flaggedForVarroa: 0,
58|           flaggedShare: 0,
59|           treatmentsPerProduct: {},
60|           honeyKilograms: 0,
61|         };
62|         regions.set(name, r);
63|       }
64|       return r;
65|     };
66| 
67|     for (const hive of this.hives.findAll()) {
68|       const apiary = this.apiaries.findById(hive.apiaryId);
69|       if (!apiary) continue;
70|       const r = regionOf(apiary.region);
71|       r.hives += 1;
72|       if (this.hiveService.isFlagged(hive.id, end)) r.flaggedForVarroa += 1;
73|       for (const t of this.treatments.findByHive(hive.id)) {
74|         if (!inQuarter(t.startDate)) continue;
75|         const name = this.products.findById(t.productId)?.name ?? t.productId;
76|         r.treatmentsPerProduct[name] = (r.treatmentsPerProduct[name] ?? 0) + 1;
77|       }
78|       for (const h of this.harvests.findByHive(hive.id)) {
79|         if (inQuarter(h.date)) r.honeyKilograms += h.kilograms;
80|       }
81|     }
82| 
83|     const list = [...regions.values()].sort((a, b) => a.region.localeCompare(b.region));
84|     for (const r of list) {
85|       r.flaggedShare = r.hives === 0 ? 0 : r.flaggedForVarroa / r.hives;
86|       r.honeyKilograms = Math.round(r.honeyKilograms * 1000) / 1000;
87|     }
